import * as THREE from 'three';

const $ = id => document.getElementById(id), scene = new THREE.Scene(), clock = new THREE.Clock(), raycaster = new THREE.Raycaster();
scene.background = new THREE.Color(0x071015); scene.fog = new THREE.Fog(0x071015, 20, 92);
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'}); renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; document.body.prepend(renderer.domElement);
const camera=new THREE.PerspectiveCamera(74,innerWidth/innerHeight,.08,180), yaw=new THREE.Object3D(), pitch=new THREE.Object3D(); yaw.add(pitch); pitch.add(camera); scene.add(yaw); camera.position.set(0,1.55,0);
const state={hp:100,armor:50,cash:2400,ammo:24,reserve:72,weapon:0,round:1,score:0,enemy:0,time:80,playing:false,planted:false,plant:0,reload:0,shot:0,shake:0,keys:{},bots:[],walls:[],feed:[],cool:0};
const weapons=[{name:'M7 CARBINE',cost:0,mag:24,stock:72,damage:34,rate:.19,spread:.012,auto:false},{name:'VX-9 BURST',cost:1500,mag:30,stock:90,damage:22,rate:.085,spread:.022,auto:true},{name:'LONGWATCH',cost:2400,mag:8,stock:24,damage:82,rate:.7,spread:.003,auto:false}];
const mat=(c,e=0,m=.2)=>new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:e,roughness:.68,metalness:m});
const cyan=mat(0x2cbcab,.35), dark=mat(0x162d31), floorMat=mat(0x14262b), coral=mat(0xd75548,.2), gold=mat(0xf0ab51,.35), glass=mat(0x1b5660,.25);
scene.add(new THREE.HemisphereLight(0x9eeeed,0x071015,1.3)); const sun=new THREE.DirectionalLight(0xbce9e5,2); sun.position.set(18,26,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
function box(x,y,z,w,h,d,material=dark,collide=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;scene.add(m);if(collide)state.walls.push(new THREE.Box3().setFromObject(m));return m}
box(0,-.2,0,82,.4,82,floorMat,false); for(let i=-36;i<=36;i+=6){box(i,.01,0,.05,.02,74,cyan,false);box(0,.01,i,74,.02,.05,cyan,false)}
// Original three-lane relay yard: north archives, central plaza, south turbine hall.
box(0,3,-38,76,7,2);box(0,3,38,76,7,2);box(-38,3,0,2,7,76);box(38,3,0,2,7,76);
[[0,0,9,7,18],[0,-20,10,5,12],[0,20,10,5,12],[-22,-14,7,17,3],[22,14,7,17,3],[-22,15,8,5,18],[22,-15,8,5,18],[-12,28,10,6,5],[12,-28,10,6,5]].forEach(a=>box(a[0],a[2]/2,a[1],a[3],a[2],a[4]));
for(const [x,z] of [[-29,-28],[29,28],[-30,27],[30,-27],[-14,-5],[14,5]]){box(x,2,z,3,4,3,glass);box(x,4.2,z,3.25,.12,3.25,cyan,false)}
const relay=new THREE.Group(); relay.position.set(0,0,-27); scene.add(relay); const core=new THREE.Mesh(new THREE.OctahedronGeometry(1.2),gold);core.position.y=2.2;core.castShadow=true;relay.add(core);relay.add(new THREE.Mesh(new THREE.CylinderGeometry(2.4,2.4,.4,8),dark)); for(let y=0;y<3;y++)relay.add(new THREE.Mesh(new THREE.TorusGeometry(1.5+y*.17,.05,6,20),cyan)).position.y=1+y*.55;
const stars=new THREE.Points(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(Array.from({length:350},()=> (Math.random()-.5)*150),3)),new THREE.PointsMaterial({color:0x75e7dc,size:.11}));scene.add(stars);
function bot(x,z,n){const g=new THREE.Group(), body=new THREE.Mesh(new THREE.CapsuleGeometry(.38,1.05,4,8),coral), head=new THREE.Mesh(new THREE.SphereGeometry(.32,12,8),mat(0xf3a47a)); body.position.y=1.03;head.position.y=1.82;body.castShadow=head.castShadow=true;g.add(body,head);g.position.set(x,0,z);g.userData={hp:100,name:n,body,head,route:Math.random()>.5?1:-1,shoot:Math.random(),alive:true,phase:Math.random()*6};scene.add(g);state.bots.push(g)}
function buildBots(){state.bots.forEach(b=>scene.remove(b));state.bots=[];bot(-27,-29,'SABLE');bot(26,-27,'KITE');bot(-28,28,'MOTH');bot(27,28,'VEIL');}
function hud(){const w=weapons[state.weapon];$('hp').textContent=Math.max(0,Math.ceil(state.hp));$('hpbar').style.width=Math.max(0,state.hp)+'%';$('armor').textContent=Math.ceil(state.armor);$('ammo').textContent=state.ammo;$('reserve').textContent=state.reserve;$('gunname').textContent=w.name+' // '+(w.auto?'AUTO':'PRECISION');$('cash').textContent=state.cash;$('friendly').textContent=state.score;$('hostile').textContent=state.enemy;$('round').textContent='ROUND '+String(state.round).padStart(2,'0');$('timer').textContent=`${String(Math.max(0,state.time/60|0)).padStart(2,'0')}:${String(Math.max(0,state.time%60|0)).padStart(2,'0')}`;$('damage').style.borderWidth=state.hp<35?'20px':'0'}
function message(t){state.feed.unshift(t);state.feed.length=4;$('feed').innerHTML=state.feed.map(x=>`<div class="feed">${x}</div>`).join('')}
function collide(p){return state.walls.some(b=>b.distanceToPoint(p)<.45)}
function resetRound(){state.hp=100;state.armor=50;state.time=80;state.planted=false;state.plant=0;state.ammo=weapons[state.weapon].mag;state.reserve=weapons[state.weapon].stock;state.feed=[];yaw.position.set(0,0,29);yaw.rotation.set(0,0,0);pitch.rotation.x=0;buildBots();state.playing=true;$('buy').classList.add('hidden');message('<b>UPLINK</b> // RELAY LIVE');hud()}
function showBuy(){state.playing=false;$('buy').classList.remove('hidden');const cards=$('cards');cards.innerHTML=weapons.map((w,i)=>`<div class="card ${i===state.weapon?'sel':''}" data-i="${i}"><h3>[${i+1}] ${w.name}</h3><p>${w.damage} DMG · ${w.mag} MAG<br>${w.auto?'Automatic close-quarter':'Controlled tactical fire'}</p><strong>${w.cost?'¢'+w.cost:'STANDARD ISSUE'}</strong></div>`).join('');cards.querySelectorAll('.card').forEach(c=>c.onclick=()=>purchase(+c.dataset.i));}
function purchase(i){const w=weapons[i];if(i===0||state.cash>=w.cost){if(i)state.cash-=w.cost;state.weapon=i;state.ammo=w.mag;state.reserve=w.stock;showBuy();hud();message('<b>ARMORY</b> // '+w.name+' EQUIPPED')}else message('<b>ARMORY</b> // INSUFFICIENT CREDITS')}
function deploy(){if(state.playing)return;state.playing=true;$('buy').classList.add('hidden');document.body.requestPointerLock?.();message('<b>UPLINK</b> // RELAY LIVE');}
function fire(){const w=weapons[state.weapon];if(!state.playing||state.reload>0||state.cool>0||!state.ammo)return;if(!state.ammo){reload();return}state.ammo--;state.cool=w.rate;state.shake=.035;const move=Math.hypot(state.keys.KeyW?1:0,state.keys.KeyS?1:0,state.keys.KeyA?1:0,state.keys.KeyD?1:0);raycaster.setFromCamera({x:(Math.random()-.5)*(w.spread+move*.026),y:(Math.random()-.5)*(w.spread+move*.026)},camera);const hit=raycaster.intersectObjects(state.bots.filter(b=>b.userData.alive),true)[0];if(hit){let b=hit.object.parent;while(b&&!b.userData.alive)b=b.parent;if(b){const head=hit.object===b.userData.head, damage=w.damage*(head?2.15:1);b.userData.hp-=damage;message(`<b>HIT ${head?'HEADSHOT':'CONFIRMED'}</b> // ${b.userData.name}`);if(b.userData.hp<=0){b.userData.alive=false;b.visible=false;state.cash+=300;message(`<b>ELIMINATED</b> // ${b.userData.name} +¢300`)}}}hud()}
function reload(){const w=weapons[state.weapon];if(state.reload||state.ammo===w.mag||!state.reserve)return;state.reload=1.35;message('<b>WEAPON</b> // RELOADING')}
function end(win,reason){state.playing=false;document.exitPointerLock?.();if(win){state.score++;state.cash+=1200}else{state.enemy++;state.cash+=800}$('result').textContent=win?'ROUND WON':'ROUND LOST';$('resultsub').textContent=reason+(win?' // +¢1200':' // +¢800');$('roundflash').style.display='grid';setTimeout(()=>{$('roundflash').style.display='none';state.round++;resetRound()},2400)}
function interact(){if(!state.playing)return;const d=yaw.position.distanceTo(relay.position);if(!state.planted&&d<4){state.planted=true;state.plant=8;message('<b>OBJECTIVE</b> // RELAY OVERRIDE INITIATED');$('objective').textContent='RELAY OVERRIDE: HOLD THE PLAZA // 00:08'}}
addEventListener('keydown',e=>{state.keys[e.code]=true;if(e.code==='KeyR')reload();if(e.code==='KeyQ'){state.weapon=(state.weapon+1)%weapons.length;state.ammo=Math.min(state.ammo,weapons[state.weapon].mag);hud()}if(e.code==='KeyE')interact();if(e.code>='Digit1'&&e.code<='Digit3'&&!state.playing)purchase(+e.code.slice(-1)-1);if(e.code==='Enter'&&!state.playing)deploy()});addEventListener('keyup',e=>state.keys[e.code]=false);addEventListener('mousedown',()=>fire());addEventListener('mousemove',e=>{if(document.pointerLockElement===document.body&&state.playing){yaw.rotation.y-=e.movementX*.0022;pitch.rotation.x=THREE.MathUtils.clamp(pitch.rotation.x-e.movementY*.0022,-1.35,1.35)}});addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
function tick(){const dt=Math.min(clock.getDelta(),.05),w=weapons[state.weapon];state.cool-=dt;state.shake=Math.max(0,state.shake-dt*.12);camera.position.x=(Math.random()-.5)*state.shake;camera.position.y=1.55+(Math.random()-.5)*state.shake;if(state.playing){state.time-=dt;if(state.reload>0){state.reload-=dt;if(state.reload<=0){const n=Math.min(w.mag-state.ammo,state.reserve);state.ammo+=n;state.reserve-=n;message('<b>WEAPON</b> // READY')}}let v=new THREE.Vector3((state.keys.KeyD?1:0)-(state.keys.KeyA?1:0),0,(state.keys.KeyS?1:0)-(state.keys.KeyW?1:0));if(v.lengthSq()){v.normalize().applyAxisAngle(new THREE.Vector3(0,1,0),yaw.rotation.y);const speed=(state.keys.ShiftLeft?.7:state.keys.ControlLeft?.35:1)*7*dt;const next=yaw.position.clone().addScaledVector(v,speed);if(!collide(next))yaw.position.copy(next)}for(const b of state.bots){if(!b.userData.alive)continue;const d=b.position.distanceTo(yaw.position),dir=yaw.position.clone().sub(b.position).setY(0).normalize();if(d>10){const next=b.position.clone().addScaledVector(dir,dt*1.35);if(!collide(next))b.position.copy(next)}b.lookAt(yaw.position.x,b.position.y,yaw.position.z);b.userData.shoot-=dt;if(d<26&&b.userData.shoot<0){b.userData.shoot=.65+Math.random()*.8;if(Math.random()<.58){let hit=12+Math.random()*10;if(state.armor){const a=Math.min(state.armor,hit*.55);state.armor-=a;hit-=a}state.hp-=hit;message('<b>INCOMING</b> // '+b.userData.name);if(state.hp<=0)end(false,'OPERATIVE DOWN')}}}if(state.planted){state.plant-=dt;$('objective').textContent='RELAY OVERRIDE: HOLD THE PLAZA // 00:'+String(Math.ceil(state.plant)).padStart(2,'0');if(state.plant<=0)end(true,'RELAY SECURED')}if(!state.bots.some(b=>b.userData.alive))end(true,'HOSTILES CLEARED');if(state.time<=0)end(false,'OVERRIDE WINDOW EXPIRED');if(state.weapon===1&&state.keys.Mouse0)fire()}core.rotation.y+=dt*1.7;core.position.y=2.2+Math.sin(performance.now()*.002)*.16;hud();renderer.render(scene,camera);requestAnimationFrame(tick)}
resetRound();const shot=new URLSearchParams(location.search).get('shot');if(shot==='plaza'){yaw.position.set(-16,0,10);yaw.rotation.y=-.55}else if(shot==='relay'){yaw.position.set(1,0,-21);yaw.rotation.y=3.14}else if(shot==='lane'){yaw.position.set(22,0,18);yaw.rotation.y=2.5}tick();
